package com.ds.goroute.controller;import com.ds.goroute.dto.BaseResponse;import com.ds.goroute.dto.request.UpsertMarketplaceReviewResponseRequest;import com.ds.goroute.dto.response.MarketplaceReviewViewResponse;import com.ds.goroute.service.MarketplaceReviewResponseService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.http.ResponseEntity;import org.springframework.security.authentication.AuthenticationCredentialsNotFoundException;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/v1/api/partner/reviews") @RequiredArgsConstructor public class PartnerMarketplaceReviewController {private final MarketplaceReviewResponseService s;@GetMapping public ResponseEntity<BaseResponse<List<MarketplaceReviewViewResponse>>> list(Authentication a,@RequestParam UUID organizationId,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="50")int size){return ResponseEntity.ok(BaseResponse.ofSucceeded(s.partnerList(user(a),organizationId,page,size)));}@PutMapping("/{reviewId}/response")public ResponseEntity<BaseResponse<MarketplaceReviewViewResponse>> respond(Authentication a,@PathVariable UUID reviewId,@RequestParam UUID organizationId,@Valid @RequestBody UpsertMarketplaceReviewResponseRequest r){return ResponseEntity.ok(BaseResponse.ofSucceeded(s.respond(user(a),organizationId,reviewId,r)));}private UUID user(Authentication a){if(a==null||a.getPrincipal()==null)throw new AuthenticationCredentialsNotFoundException("Authentication required");Object p=a.getPrincipal();return p instanceof UUID id?id:UUID.fromString(p.toString());}}
